package com.bionote.agent.runtime;

import com.bionote.agent.model.AgentModelClient;
import com.bionote.agent.model.AgentModelRequest;
import com.bionote.agent.model.AgentModelResponse;
import com.bionote.agent.model.ModelClientException;
import com.bionote.agent.model.ModelToolCall;
import com.bionote.agent.prompt.PromptVersion;
import com.bionote.agent.prompt.PromptVersionService;
import com.bionote.agent.tool.AgentToolContext;
import com.bionote.agent.tool.AgentToolExecutor;
import com.bionote.agent.trace.AgentTraceRecorder;
import com.bionote.agent.validation.AgentResultValidator;
import com.bionote.agent.validation.ValidationResult;
import com.bionote.common.ApiException;
import com.bionote.collaboration.event.AgentRunFailedEvent;
import com.bionote.collaboration.event.AgentRunSucceededEvent;
import com.bionote.collaboration.event.DomainEventPublisher;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Service
public class AgentHarness {
    private final AgentRunRepository runs;private final PromptVersionService prompts;private final AgentContextBuilder contexts;private final AgentModelClient model;private final AgentPlanner planner;private final AgentToolExecutor tools;private final AgentResultValidator validator;private final AgentTraceRecorder trace;private final ObjectMapper json;private final DomainEventPublisher events;
    public AgentHarness(AgentRunRepository runs,PromptVersionService prompts,AgentContextBuilder contexts,AgentModelClient model,AgentPlanner planner,AgentToolExecutor tools,AgentResultValidator validator,AgentTraceRecorder trace,ObjectMapper json,DomainEventPublisher events){this.runs=runs;this.prompts=prompts;this.contexts=contexts;this.model=model;this.planner=planner;this.tools=tools;this.validator=validator;this.trace=trace;this.json=json;this.events=events;}
        public void execute(UUID runId){AgentRunRecord initial=runs.load(runId);if(!"RUNNING".equals(initial.status()))return;PromptVersion prompt=prompts.get(initial.promptVersionId());AgentLimits limits=AgentLimits.parse(json,initial.limitsJson());AgentRunMemory memory=new AgentRunMemory();Instant deadline=initial.startedAt().plusMillis(limits.maxDurationMs());trace.record(runId,"RUN_STARTED",null,Map.of("artifactKind",initial.artifactKind(),"subjectType",initial.subjectType(),"promptVersionId",prompt.id()),null,0,0,0);try{while(true){AgentRunRecord run=runs.load(runId);if(runs.cancelRequested(runId)){terminal(runId,"CANCELLED","AGENT_CANCELLED","Agent run cancelled");return;}if(Instant.now().isAfter(deadline)){terminal(runId,"FAILED","AGENT_TIMEOUT","Agent run deadline exceeded");return;}if(memory.executionSteps()>=limits.maxSteps()){terminal(runId,"LIMIT_EXCEEDED","AGENT_LIMIT_EXCEEDED","Agent execution step limit exceeded");return;}if(memory.modelCalls()>=limits.maxModelCalls()){terminal(runId,"LIMIT_EXCEEDED","AGENT_LIMIT_EXCEEDED","Model call limit exceeded");return;}memory.incrementExecutionSteps();AgentRunContext context=new AgentRunContext(run,prompt,memory,limits,deadline);AgentModelRequest request=contexts.build(context);trace.record(runId,"MODEL_REQUEST",null,Map.of("provider",model.provider(),"model",run.model(),"toolNames",request.tools().stream().map(value->value.name()).toList(),"promptVersionId",prompt.id()),null,0,0,0);long started=System.nanoTime();AgentModelResponse response=model.complete(request);long latency=(System.nanoTime()-started)/1_000_000;memory.incrementModelCalls();trace.record(runId,"MODEL_RESPONSE",null,null,Map.of("toolCalls",response.toolCalls().stream().map(ModelToolCall::name).toList(),"hasFinal",response.finalOutput()!=null,"errorCode",response.errorCode()==null?"":response.errorCode()),latency,response.inputTokens(),response.outputTokens());if(runs.cancelRequested(runId)){terminal(runId,"CANCELLED","AGENT_CANCELLED","Agent run cancelled");return;}PlannerDecision decision=planner.next(new AgentRunContext(runs.load(runId),prompt,memory,limits,deadline),response);if(decision instanceof PlannerDecision.Fail failed){terminal(runId,statusFor(failed.code()),failed.code(),failed.message());return;}if(decision instanceof PlannerDecision.ExecuteTools execute){memory.addMessage(new AgentModelRequest.ModelMessage("assistant",null,null,null,execute.invocations()));for(ModelToolCall call:execute.invocations()){AgentRunRecord current=runs.load(runId);if(memory.executionSteps()>=limits.maxSteps()){terminal(runId,"LIMIT_EXCEEDED","AGENT_LIMIT_EXCEEDED","Agent execution step limit exceeded");return;}if(current.toolCallCount()>=limits.maxToolCalls()){terminal(runId,"LIMIT_EXCEEDED","AGENT_LIMIT_EXCEEDED","Tool call limit exceeded");return;}memory.incrementExecutionSteps();trace.record(runId,"TOOL_CALL",call.name(),Map.of("callId",call.id(),"arguments",call.arguments()),null,0,0,0);AgentToolContext toolContext=new AgentToolContext(runId,current.requestedBy(),current.projectId(),current.recordId(),current.subjectType(),current.subjectId(),current.artifactKind(),deadline,()->runs.cancelRequested(runId));AgentToolExecutor.ExecutedToolResult result=tools.execute(toolContext,call.name(),call.arguments(),prompt.allowedTools(),memory);runs.incrementToolCalls(runId,1);trace.record(runId,"TOOL_RESULT",call.name(),null,Map.of("summary",result.summary(),"resultHash",result.resultHash(),"evidenceCount",result.evidenceCandidates().size(),"truncated",result.truncated(),"cached",result.cached()),0,0,0);memory.addMessage(new AgentModelRequest.ModelMessage("tool",toolMessage(result),call.id(),call.name()));}continue;}PlannerDecision.Finish finish=(PlannerDecision.Finish)decision;AgentRunContext validationContext=new AgentRunContext(runs.load(runId),prompt,memory,limits,deadline);ValidationResult validation=validator.validate(validationContext,finish.candidateArtifact(),prompt.outputSchema());trace.record(runId,"VALIDATION",null,null,Map.of("valid",validation.valid(),"errors",validation.errors()),0,0,0);if(!validation.valid()){if(memory.repairTurns()<limits.maxRepairTurns()){memory.incrementRepairTurns();memory.addMessage(new AgentModelRequest.ModelMessage("user",write(Map.of("validationErrors",validation.errors(),"instruction","Return a corrected JSON object only.")),null,null));continue;}terminal(runId,"INVALID_OUTPUT",validation.errors().stream().anyMatch(value->value.startsWith("EVIDENCE:"))?"AGENT_EVIDENCE_INVALID":"AGENT_INVALID_OUTPUT",String.join("; ",validation.errors()));return;}JsonNode evidence=finish.candidateArtifact().path("evidence");UUID artifact=runs.completeWithArtifact(runId,finish.candidateArtifact(),evidence.isMissingNode()?json.createArrayNode():evidence);trace.record(runId,"ARTIFACT_SAVED",null,null,Map.of("artifactId",artifact),0,0,0);return;}}catch(ModelClientException e){terminalIfRunning(runId,statusFor(e.code()),e.code(),e.getMessage());}catch(ApiException e){String status="AGENT_RUN_CANCELLED".equals(e.code())?"CANCELLED":statusFor(e.code());terminalIfRunning(runId,status,e.code(),e.getMessage());}catch(Exception e){terminalIfRunning(runId,"FAILED","AGENT_RUNTIME_FAILED","Agent runtime failed");}}
    private String statusFor(String code){if("AGENT_INVALID_OUTPUT".equals(code))return "INVALID_OUTPUT";if(code!=null&&code.contains("LIMIT"))return "LIMIT_EXCEEDED";return "FAILED";}
    private void terminalIfRunning(UUID id,String status,String code,String message){if("RUNNING".equals(runs.load(id).status()))terminal(id,status,code,message);}
    private void terminal(UUID id,String status,String code,String message){AgentRunRecord run=runs.load(id);trace.record(id,"RUN_FAILED",null,null,Map.of("status",status,"errorCode",code,"message",message==null?"":message),0,0,0);runs.finish(id,status,code,message);events.publish(new AgentRunFailedEvent(UUID.randomUUID(),run.requestedBy(),run.projectId(),run.recordId(),Instant.now(),id,run.artifactKind(),run.triggerType(),status,code));}
    private String toolMessage(AgentToolExecutor.ExecutedToolResult result){if(!result.cached())return result.data().toString();JsonNode notice=json.createObjectNode().put("cached",true).put("instruction","This exact tool call was already executed. Reuse this result and do not request the same tool with the same arguments again.");if(result.data().isObject()){var value=(com.fasterxml.jackson.databind.node.ObjectNode)result.data().deepCopy();value.set("_runtime",notice);return value.toString();}return write(Map.of("data",result.data(),"_runtime",notice));}
    private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException(e);}}
}
